    static func lookup(_ name: String) -> (regular: Cut, bold: Cut?)? {
        switch name {
        case "malgun gothic", "맑은 고딕": return malgun
        case "sitka heading": return sitkaHeading
        case "sitka heading semibold": return sitkaHeadingSemibold
        case "meiryo", "メイリオ": return meiryo
        case "meiryo ui": return meiryoUI
        // (PowerPoint draws the AR P / AR Maru / BIZ UDP gothics it lacks in Yu Gothic: ja-64f938d1 p10's "AR Pゴシック体M" has a full-em ，.)
        case "yu gothic", "游ゴシック", "adobe fan heiti std b", "ar pゴシック体m", "ar pゴシック体e", "ar pゴシック体l", "ar pゴシック体b", "ar pゴシック体h", "ar p丸ゴシック体m", "ar p丸ゴシック体e", "ar丸ゴシック体m", "ar丸ゴシック体e", "biz udpゴシック": return yuGothic
        case "yu gothic light", "游ゴシック light": return yuGothicLight
        case "yu gothic medium", "游ゴシック medium": return yuGothicMedium
        case "yu gothic ui": return yuGothicUI
        case "ms pgothic", "ｍｓ ｐゴシック": return msPGothic
        case "ms gothic", "ｍｓ ゴシック": return msGothic
        case "ms ui gothic", "ｍｓ ｕｉ ゴシック": return msUIGothic
        case "ms mincho", "ｍｓ 明朝": return msMincho
        case "ms pmincho", "ｍｓ ｐ明朝": return msPMincho
        case "hgゴシックe", "hgｺﾞｼｯｸe", "hg gothic e": return hgGothicE
        case "hg丸ゴシックm-pro", "hg丸ｺﾞｼｯｸm-pro", "hgmarugothicmpro": return hgMaruGothic
