        case "nunito black": return nunitoBlack
        case "baskerville old face": return baskervilleOldFace
        case "hgpゴシックe", "hgpｺﾞｼｯｸe", "hgpgothice": return hgPGothicE
        case "hgsゴシックe", "hgsｺﾞｼｯｸe", "hgsgothice": return hgSGothicE
        case "hg創英角ゴシックub", "hg創英角ｺﾞｼｯｸub", "hgsoeikakugothicub": return hgSoei
        case "hgs創英角ゴシックub", "hgs創英角ｺﾞｼｯｸub", "hgssoeikakugothicub": return hgSSoei
        case "ud デジタル 教科書体 nk-b", "ud digi kyokasho nk-b": return udKyokashoNK
        case "ud デジタル 教科書体 np-b", "ud digi kyokasho np-b": return udKyokashoNP
        case "microsoft jhenghei", "微軟正黑體": return jhengHei
        case "tw cen mt": return twCenMT
        case "noto sans": return notoSans
        case "comic sans ms": return comicSans
        case "gungsuh", "궁서": return gungsuh
