        case "lucida console": return lucidaConsole
        case "jokerman": return jokerman
        case "chiller": return chiller
        case "segoe ui historic": return segoeUIHistoric
        case "agency fb": return agencyFB
        case "arial narrow": return arialNarrow
        case "arial rounded mt bold": return arialRounded
        case "bahnschrift": return bahnschrift
        case "berlin sans fb": return berlinSans
        case "berlin sans fb demi": return berlinSansDemi
        case "bodoni mt": return bodoniMT
