        case "constantia": return constantia
        case "cooper black": return cooperBlack
        case "courier new": return courierNew
        case "franklin gothic heavy": return franklinGothicHeavy
        case "franklin gothic medium": return franklinGothicMedium
        case "garamond": return garamond
        case "impact": return impact
