    /// The italic cuts of the faces that have measured ones (regular = italic, bold = bold italic).
    static func lookupItalic(_ name: String) -> (regular: Cut, bold: Cut?)? {
        switch name {
        case "tw cen mt": return twCenMTItalic
        case "sitka heading": return sitkaHeadingItalic
        case "noto sans": return notoSansItalic
        case "comic sans ms": return comicSansItalic
        case "georgia": return georgiaItalic
        case "raleway": return ralewayItalic
        case "rockwell": return rockwellItalic
        case "tenorite": return tenoriteItalic
        case "bierstadt": return bierstadtItalic
        case "aptos display": return aptosDisplayItalic
        case "nunito sans": return nunitoSansItalic
        case "gill sans mt": return gillSansMTItalic
        case "franklin gothic book": return franklinGothicBookItalic
        case "montserrat": return montserratItalic
        case "arial narrow": return arialNarrowItalic
        case "bodoni mt": return bodoniMTItalic
        case "book antiqua": return bookAntiquaItalic
        case "century schoolbook": return centurySchoolbookItalic
        case "constantia": return constantiaItalic
        case "courier new": return courierNewItalic
        case "franklin gothic medium": return franklinGothicMediumItalic
        case "franklin gothic heavy": return franklinGothicHeavyItalic
        case "garamond": return garamondItalic
        case "open sans": return openSansItalic
        case "roboto": return robotoItalic
        case "source sans pro": return sourceSansProItalic
        case "brush script mt": return brushScriptItalic
        default: return nil
        }
    }
}
